('av_1RRksVLBiOwD22HbbRGX6t8h6GK54uMFRzOnfkfY5nl6TdfCKnxosCyC_u8RFnZx53nndc1CId5fZ_0','我的妈耶',2026,'movie','中国大陆',NULL,'["喜剧","剧情","家庭","电影"]','["白客","黄明昊","马思纯","孙阳","梁靖康","郭虹","嵇嘉禾","孔连顺","雷淞然","王天放","张子贤","丁子玲"]','["肖麓西"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/50/50c329e398e470b13a24b78a35c8553f9867adff768731ec77702f122c9c560a.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/76/76f777764d2d6a907503d3d3c3527d476f1a61aca09645264afc96b66fb6f3e1.webp','十一(黄明昊 饰)从小由父亲张永勋(白客 饰)独自抚养长大,自出生时就离世的妈妈东玉(马思纯 饰)对于他而言则是陌生人般的存在。处于青春叛逆期的十一,在自己18岁生日这天意外发现了一本「妈妈的日记」。在好奇心的驱使下,十一翻开日记,开启了一段“认识妈妈”的旅程——十一跟随着妈妈的成长经历,邂逅了她人生不同阶段的重要人物——霹雳舞学长(梁靖康 饰)、高中闺蜜彩霞(嵇嘉禾 饰)、发小刘皮孩(王天放 饰)、初恋小哥(孙阳 饰)以及老公张永勋。这些人物串联起东玉一生所经历的友谊、爱情与亲情...... 透过这本「日记」,十一看见了东玉短暂却向阳的一生,也终于感受到了她对自己从始至终不曾缺席的爱......','高清',1,1,85.06,'最近上线 正片'),
('av_1VsyavHW-pkpgRMMiOrC89uIAhcm0LENSY1YqXfDnoMJGR7N6sVrrMg45G_o-iljIGRpW8f8JAt11C4','三国',2010,'series','中国大陆','国语','["国产剧","剧情","历史","战争","内地","国产"]','["安彭泽宇","常铖","陈好","陈建斌","范雨林","何润东","黄维德","霍青","焦晃","康凯","李建新","李依晓"]','["高希希"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/d2/d246f716b0fe36a149683737134def8fef1b7ba5e15cae8b298906f7a32aa44f.webp',NULL,'东汉末年,朝纲混乱。内有董卓(吕晓禾 饰)巨奸权倾朝野,专横跋扈;外有黄巾军起义,撼动社稷。时有曹操(陈建斌 饰)韬光养晦,欲为国除害。逃出京城后,曹操与各地诸侯袁绍、刘备(于和伟 饰)、孙坚等二十路豪杰会盟,共同讨伐董卓。几番征战,董卓最终死于义子吕布(何润东 饰)之手。此时大汉气数将近,英雄豪杰皆觊觎天下,因此上演了群雄逐鹿的争霸大戏。关羽(于荣光 饰)、张飞、诸葛亮(陆毅 饰)、周瑜、夏侯渊、陆逊、姜维、司马懿(倪大宏 饰)等风云人物相继入世,魏、蜀、吴三分天下,千古传奇流传至今...... 本片根据中国古典四大名著之一《三国演义》改编。','全95集',95,95,140.9,'2026-11-10T17:25:11.135Z'),
