('av_2Nrbq1T5nvIOimb7pkjrtImE3vMuo9mx8_MjNAupAM4-yuT5aXD2apHtmf1Jli2c_OX2GOtpPhZa568','迷你特工队X',2018,'anime','中国大陆','国语','["国产动漫","动漫"]','["福乐 小米 路茜 麦思","福乐","路茜","麦思","小米"]','["施忠","李永俊"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/19/19f6707d347955ac757aaf5650de718f46ec68c7aca6aac06cce49189f765b26.webp',NULL,'在浩瀚的宇宙中,经过长期岁月辗转,被秘密选召出的四个小动物,作为“迷你特工队”保护地球的和平,他们是最强战士:弗特、赛米、露西、麦克斯!数百年后宇宙海盗丹丹团三人组——卡拉、丹特、丹乔,在某个小行星发现了被封印的外星人杰苏,并解开封印让其重见天日。杰苏的力量源于生命体所散发出的负面情感(恐惧、伤心),被称作不幸能量。这伙邪恶势力筹划在地球不断制造危机,并从地球上的生命体获得不幸能量。 迷你特工队为保护地球,与邪恶势力展开了激烈的战斗!','全52集',52,52,76.85,'最近更新 第52集'),
('av_2P3cDuTbMlN3fglj_aqHF4VBka35-ucjJC6ZjlDfEnHe7bc2SDFXBdtL22evTHIuPtcVcdMHKbkIOeM','黑子的篮球 第1季',2012,'anime','日本','日语','["日本动漫","动漫","日韩动漫","竞技"]','["小野贤章","小野友树","斋藤千和","细谷佳正","江口拓也","小野大辅","铃村健一","木村良平","野岛裕史","神谷浩史","保志总一朗","谷山纪章"]','["多田俊介","滨名孝行","池田重隆","龟井干太","加户誉夫","京极义昭","驹屋健一郎","林直孝"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/bb/bbb0344cbc4089b9ac850ba3e23533301c3dcdb25984efc1c36514ed783adb5c.webp',NULL,'《黑子的篮球》故事主要围绕两位主人公——被誉为第六位“奇迹世代”的黑子哲也以及从美国归来的天才篮球选手火神大我展开,两人在球场上市光与影的搭档。相遇后的他们将挑战其他五位“奇迹世代”。','全26集',26,26,70.7,'最近更新 第26集'),
('av_2PcZRBCL5xoPaneJTdaetMh7aVHzUg_IEYD41DBrtZ5QVWurdOb-x8rM7jNpc-Ugt_Kzjsa-pS2y-sk','下班!去约会',2022,'variety','中国大陆','国语','["综艺","大陆综艺","真人秀","情感"]','["布鲁诺·坎波斯","乔·鲍里托","Albert","Alix","E.","Edward","Estes","Gaven","Koromzay","Lucas","Will"]','["让·德·塞贡扎克"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/e5/e5062f264c030e284c3cac37f890f44908a1b77cfd147d87348c64dc79bc7319.webp',NULL,'《下班!去约会》是一档「兴趣匹配」「自主选择」「好玩不尬」,为有趣的灵魂量身定制的解压社交节目,每期6-8位男女嘉宾,通过大数据与个人选择进行自由交友邀约每一个独特闪光的个体,都期待着那个同样闪光的TA。','2022-12-14 第6期下',36,36,56.1,'2026-11-13T11:51:18.235Z'),
('av_2Q5yEICm3jNtl2JRDlUzKhyROMHI46ytOuxe7SeuYj532hMbWZPx77uaAYdy0cyGdQlHSVbCdDyRALA','康熙来了',2004,'variety','中国台湾','国语','["港台综艺","脱口秀","综艺"]','["蔡康永","陈汉典","徐熙娣","安钧璨","曹西平","陈孝萱","川岛茉树代","狄莺","费贞绫","黄嘉千","简莉纹","李玟"]','["王伟忠","陈彦铭","詹仁雄"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/c3/c322ef82933896e9994032ad4b425cbb976a3f0ae2004419efb4a8ed6655d98c.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/53/5374d0248d2f831ce57adae863807f1ac0a939568ab1e70e2cefc7dced6fc323.webp','搞怪天后徐熙娣與才子頑童蔡康永聯手主持的『康熙來了』,自2004年推出以來,已製播超過一千集,節目收視率與人氣度年年成為台灣最受觀眾喜愛與最受媒體矚目的綜藝焦點。©中天电视台','2016-01-14',4155,4155,75.6,NULL),
('av_2Rfxzw2dXIuThi8-wHhfr1dpnVazsBaQ0bgd2sP0jH2gti2RiTAinjY02dFo-8xl6ksc3lPV2N3kW9w','演员请就位 第2季',2020,'variety','中国大陆','国语','["大陆综艺","真人秀"]','["陈凯歌","白凯南","卜冠今","曹斐然","陈腾跃","代高政","戴向宇","方力申","高梓淇","贺美琦","黄灿灿","黄子琪"]','["孙亮亮","未录入"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/d3/d3470b3238e5ef80479e7f23fb52a470d7618cc0303473bddb26f02977562ff6.webp',NULL,'以影视行业演员的生存现状为策划依托,还原行业选角、定妆试戏、争取角色、跑组排练、片场拍摄等一系列真实过程,围绕新一季节目核心理念「帮助演员找到属于自己的赛道」分成4个阶段。 第一阶段:还原影视行业真实选角过程,46位演员进入节目,经历海选群面、简历定级、赛道选择、首轮试戏面试等一系列考核。保留最经典的SAB定级模式,考核后演员获得最终评级后决定去留。第二阶段:还原真实的跑组生态,演员们分小组进入不同剧组试戏,争取角色。演员们每获得一个角色同时获得背后对应的不同分值,最终以演员们演出的角色的总分数及片场表演水平评判考核结果。第三阶段:演员自由选择搭档和想要挑战的赛道,完成不同热门经典IP短片的拍摄,最终通过观众考核及导师看片评价等多方维度的综合评判,选出进入最终盛典的演员。第四阶段:两位导师下场、飞行导师助力,带领演员们完成终极影视化作品的拍摄。作品将...','2020-12-05',56,56,56.29,'2026-11-13T12:08:09.327Z');
INSERT INTO shows(id,title,year,content_kind,area,language,genres,actors,directors,poster,backdrop,description,remarks,episode_count,available_episode_count,heat_value,updated_at) VALUES
('av_2TBd0ItZyE-eJguR5u2RsmLbU9G5-WXLrxCIDwf3dD1ArqYW8rtkocReI5_bkCtMeOLPZJQfI8tJvME','后会有期',2011,'movie','比利时',NULL,'["剧情"]','["Gilles De Schrijver","Xandra Van Welden"]','["Geoffrey Enthoven"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/9f/9fcfe317603ecca133cc68f689f6e64dafd2dc7f019b7b6c7d029adc40f8edd0.webp',NULL,'“Hasta la Vista”可不是阿诺在《终结者》中拽拽地说出的名台词,而是西班牙一所妓院的妓女们热情好客的欢送语。三位主人公是一名盲人,一名半身麻痹着和一名全身瘫患者,但是他们相信,像他们这样的人也有权利追求爱和性,所以三人本着“破处”的目的向着西班牙一家为残疾人提供服务的妓院出发了......','高清',1,1,76.25,'最近上线 正片'),
('av_2UPrXXluHXTDrWfP0p7oa765IXMV0B-mDQwDuIs7FneNVffncEz6AY9IVywk-YY3_4DZYGYXqQ63caA','龙临喀布尔',2025,'movie','匈牙利',NULL,'["战争","动作"]','["加博·贾斯贝埃尼","布兰卡·梅萨罗斯","Tamás Borovics","哈里·索维克","诺拉·特罗坎","Ádám Egri","Adrian Samudovszky","Blanka Mészáros","Dávid Hajmási","Gábor Hegedűs","Gusztáv Dietz","Klarissza Lakatos"]','["宗博尔·迪加","Zsombor Dyga"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/8f/8f77adb8502b26e65ca930393d67395bb9dc613668f4ed3a5194b934bd88921b.webp',NULL,'2021年北约撤军阿富汗期间,喀布尔局势全面失控。匈牙利国防军接到秘密任务,执行“萨满之盾”撤离行动,在被围困的机场与城市中撤出540名平民,其中包含180名儿童。特战小队在炮火与混乱中穿梭,一边对抗步步紧逼的武装势力,一边护送平民突围。行动过程中,队长意外重逢失联多年的爱人,任务与私人情感交织,所有人都要在绝境里做出抉择。','高清',1,1,79.34,'最近上线 正片'),
('av_2UeKMeoTzYNzgvZtpZAwlF_P5fzwShf8wqTAkawjV75ZzI6waSKSILwvMfD6DuKIX2_1XMSMruZ9kIg','装腔启示录',2023,'series','中国大陆','国语','["国产剧","剧情","爱情","国产","电视剧"]','["包上恩","蔡文静","代云帆","耿乐","韩东君","柴隽哲","陈伟栋","丁楠","甘昀宸","黄维德","蒋诗萌","李媛"]','["李漠","李江明"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/be/beeec82f37ec0776b6e4399e47d98e5597e0fdb77595dac6997ea1638dbedf4b.webp',NULL,'本剧改编自豆瓣阅读连载小说《装腔启示录》,作者柳翠虎。 繁华都市,流光浮华的红男绿女,平行的唐影和许子诠在飞机上偶遇,于是展开了一段暧昧博弈,互相撩拨的情爱故事。倔强勇敢当仁不让的律师唐影、自信温柔成熟魅惑的投行VP许子诠,两性吸引之下,这对戴着都市假面的成年男女经历 了从相爱到敢爱的求索之旅。','全22集',22,22,122.39,'2026-11-09T10:24:34.469Z'),
('av_2VbX5xDkgwdeRQXHMRBTwVVzc4vRqsehc5G3x9KStY-dX7IwGGsE-a9T6_VlY3a9sTDac5LXBlyP07Q','笔仙惊魂',2012,'movie','中国大陆','国语','["恐怖","悬疑","惊悚"]','["何杜娟","柴碧云","翟子陌","付曼","王一","午马"]','["关尔"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/6d/6d1898ac76936c748c5f19fc5bcd838e83b04a34a1b13e32c3fce22beb7a8cd8.webp',NULL,'某艺术院校学生小武(翟文斌 饰)、慕凡(王一 饰)、柳丝丝(何杜鹃 饰)、凌菲儿(柴碧云 饰)驱车来到位于郊外,租住了当地的四合院。这是一座古色古香但是颇为阴森的老宅,周围的住户似乎对此也多有忌惮,欲言又止。夜深人静,四合院突然断电。四个青年男女无聊至极,决定玩传说中的禁忌游戏笔仙。但是无所畏惧懵懂无知的小武竟然问起了笔仙的死因,之后也未将笔仙送走。在此之后,诡异的事情接连发生,半夜从远处传来的戏曲念白,挂满死猫的树,柳丝丝深更半夜的恐怖举止......如是种种,无一不在搅扰着年轻人们的神经。 恐怖的究竟是这个院落还是毫无形状的笔仙,抑或是......','高清',2,1,65.08,'最近上线 笔仙惊魂3'),
('av_2VsAzMW6YwXJdpjyqqsRwWfht7xMRtkb-yPj_a0-uGeGOcnw4tsKPICPItb8_U9NKLSACe9QcUN7fK4','阿吽:万物之初与尽',2011,'movie','日本',NULL,'["科幻","奇幻"]','["Tenji Kamogawa","William Ferreira","Yûki Hiyori"]','["埃德加·霍内特施莱格"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/c0/c0c1dbebbb45f7b45acc7151f0cfe9f8a952676fe881a9aab6ade4a61b7dfd3e.webp',NULL,'日本科学家世界[=世界]为了人类的光明未来,发明了一种燃烧水的发动机。他的妻子光(Hikari)[=光]在生下儿子阿恩(Aun)[万物的开始和终结]时去世。作为一个蹒跚学步的孩子,阿恩在海滩上发现了一只不寻常的海蜗牛。世海用它来进行涉及他自己身体的实验,最终杀死了他。二十年后,来自巴西国会大厦(现代主义巴西利亚)的聋哑科学家欧几里得斯(=数论学家)继续进行 Sekai 的实验。他相信海蜗牛是通往宜居未来的缺失环节,因此要求他的妻子宁法(Nympha)[=蝴蝶的蛹期]找到阿恩。当她发现阿恩曾经在东京赌博时,她与日本黑帮一起玩一种古老的日本纸牌游戏。森林里的仙女派给她一位精灵使者,带她去见阿恩——她现在在神社担任牧师。痴情占据了他们。宁法进入世界所设想的世界。欧几里得斯现在与他的项目的赞助商发生了麻烦,他让他的妻子带他去安恩的神社。当他们到达时,年纪惊人的阿恩将海蜗牛交给了欧几里德斯。很高兴后者进行了实验,而他的妻子则试图找到回到她曾经体验过的世界的方法。欧几里德斯很高兴,因为他相信自己已经成功地创造了“未来”。仙女们对他施了咒语。欧几里得斯去世。他用最后一口气呼出一种物质,使世界从宇宙中消失。《AUN——万物的开始与终结》讲述了人类对未来的追寻、对创造明天的渴望、对末日的恐惧和厌恶。它两次旋转了浮士德式的主题,暴露了犹太/基督教对进步的无穷无尽的信念,到了21世纪,这种信念已经占领了整个世界,并成功地将地球引入了一种无法再通过经济和科学来解决的局面。启蒙运动的优点在于西方有能力感知那些看不见的东西和只能感觉到的东西。信仰不仅仅是宗教,也不仅仅是一神论的概念。灵魂和精神不仅仅存在于电影中。否认和忽视永恒法则会导致个人和整个人类的灭绝。 AUN 发明了仪式和神话,并通过有趣地展示自然与人类文化的二分法来崇拜这一切的创造者——自然。影片将人类的美丽与自然等同起来,宣称“人类在大自然中创造的一切”。可悲的是,狂妄自大的结束让观众有机会为世界衷心哭泣。','高清',1,1,94.12,'最近上线 正片'),
