('av_4M8WxK6oBGtN8xXckAudxYjg7xUelIlH5DL7-usbuPso3isFwuFFv5LIogjeJi7PaC3CWVLDEnOZKiI','沙丘',2021,'movie','美国',NULL,'["剧情","科幻","冒险","动作","院线","奇幻","战争","电影","4K电影"]','["奥斯卡·伊萨克","丽贝卡·弗格森","戴夫·巴蒂斯塔","杰森·莫玛","赞达亚","乔什·布洛林","巴布斯·奥卢桑莫昆","保罗·布林","比约恩·弗赖贝格","查理·罗尔斯","大卫·达斯马齐连","格洛里亚·奥比安约"]','["丹尼斯·维伦纽瓦","未录入"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/68/681d05738b35f84d388d6ddda89cb0737462d207bc967ce9b7f6e266bfefe128.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/26/2652c29dc8da468a3a4958ce43d7e1b7b404d705187d5ac09496b5b3e144b7ba.webp','电影《沙丘》为观众呈现了一段神秘而感人至深的英雄之旅。天赋异禀的少年保罗·厄崔迪被命运指引,为了保卫自己的家族和人民,决心前往浩瀚宇宙间最危险的星球,开启一场惊心动魄的冒险。与此同时,各路势力为了抢夺这颗星球上一种能够释放人类最大潜力的珍贵资源而纷纷加入战场。最终,唯有那些能够战胜内心恐惧的人才能生存下去。','高清',2,1,119.13,'最近上线 沙丘Dune'),
