('av_5hKa0CB_w4zRbHb-VmrPvpAZbK4tWkRSw9Wy7zlu6a4GZ39bwWETlyT_RIS1Sp49K7VzqHRZqfTxb30','禁忌 第1季',2017,'series','英国','英语','["欧美剧","欧美","剧情","电视剧","美剧"]','["奥娜·卓别林","里奥·比尔","理查德·迪克森","汤姆·哈迪","爱德华·霍格","大卫·海曼","弗朗卡·波滕特","杰佛逊·豪尔","杰森·沃特金斯","杰西·巴克利","罗杰·阿什顿-格里菲斯","马克·加蒂斯"]','["克里斯托弗·尼霍姆","安德斯·恩格斯特伦","安德斯·恩斯特朗"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/2c/2c79be168f171fff989d9bf201c4923170f703abefdc3d40e61a9c5f1ff05f2e.webp',NULL,'Tom Hardy新剧《Taboo》这周在伦敦开拍,由BBC One和FX共同制作,Michael Kelly和Jonathan Pryce加盟本剧。本剧是Hardy在《浴血黑帮 Peaky Blinders》和《Locke》之后和Steven Knight的又一次合作。 Hardy 将在本剧中饰演James Keziah Delaney,1814年的他发现在非洲生活十年之后,他父亲留给自己一笔神秘的遗产;后来被误解他的人带入发动了战争,他又发现自己与东印度公司呈现对峙的状态,同时在英美两个参战国之间进行着一个危险的游戏。 Kelly将饰演一个美国医生;Pryce将饰演Stuart Strange爵士,东印度公司的长官,也是Delaney主要对手;Oona Chaplin饰演Zilpha Geary,Delaney同父异母的姐姐; David Hayman饰演忠诚的仆人Brace。 此外参演的演员还有Jessie Buckley 、 Ashley Walters、Jefferson Hall、Ed Hogg、Leo Bill、Christopher Fairbank、Richard Dixon、Jason Watkins和Nicholas Woodeson。 根据此前的报道,Kristoffer Nyholm将担任导演,Mark Patten担任摄影导演,Sonja Klaus担任艺术指导,Joanna Eatwell担任服装设计,Nina Gold担任选角导演。','全8集',8,8,78.33,'2026-11-13T12:10:50.436Z'),
('av_5hl5jxpKYsaLkOhb6ixqMxAHYrNOF-Dg_8ZCYdSB7l6hP2XJ9XvqdepkMcYu5J7FdFxlsWAN2N4upO8','唐人街探案3',2021,'movie','中国大陆',NULL,'["喜剧","悬疑","电影"]','["刘昊然","妻夫木聪","托尼·贾","长泽雅美","陈思诚","陈哲远","程潇","崔雨鑫","克拉拉","李明轩","铃木保奈美","刘德华"]','["陈思诚"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/98/98491b7dbf1aa4ae6e0e91823c55f9bb0c77ac7b38eaad32aaa57095bc1fb434.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/ad/adc3a3fa87ec77d27d616774c0bf7cedea60f43aa4f6da96bd154f7dab7494bd.webp','继曼谷、纽约之后,东京再出大案。唐人街神探唐仁(王宝强 饰)、秦风(刘昊然 饰)受侦探野田昊(妻夫木聪 饰)的邀请前往破案。“CRIMASTER世界侦探排行榜”中的侦探们闻讯后也齐聚东京,加入挑战,而排名第一Q的现身,让这个大案更加扑朔迷离,一场亚洲最强神探之间的较量即将爆笑展开......','高清',1,1,98.04,'最近上线 正片'),
('av_5hslVBncF3BnfpHBeGlrZMYuPkrYbBxdNDzsMF5GHQTOTzNYTfXq_GYzDC4Oa6npy-MQmUC471HeJv8','问心2',2026,'series','中国大陆','国语','["国产剧","国产","剧集","剧情","连续剧","都市","连续","集","电视剧"]','["金世佳","毛晓彤","张佳宁","赵又廷","陈冲","合诗雨","黄觉","孙浠伦","王川","扈耀之","牟湘盈","苑冉"]','["黎志"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/21/21b2b8fdc372c7edcac6749167d1d056d4dc86c3a14b19b76baf9cd711a8dd21.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/ab/abbd257b13b115b2096f03411f37fa43ebb4a393ebe2607bbb80193eb1fd121e.webp','两年后,周筱风援黔归来与林逸、方筱然会合,三人小分队再度并肩作战,但也面对全新挑战。周筱风自身执着奋进且严守医疗原则,机缘之下被破格提拔为东立医院史上最年轻的心内科执行主任。职位的晋升,让他看到了更多可能、面临更大考验,也颠覆了他与林逸方筱然间原本的关系,甚至医院内外的生态平衡也因此被打破。与此同时,他们还需要面对医生永远的对手——病魔。一个接一个的病人与他们身后的家庭期待医护联手拯救。理想与现实时时冲突,无奈和温暖往往共生,他们只有在奋斗中不断成长,继续保持着“问心无愧”。','全40集',40,40,123.44,'2026-11-12T17:34:36.594Z'),
